module div_16bit(
    input [15:0] A, input [7:0] B,
    output reg [15:0] result, output reg [15:0] odd
);
    always @* begin
        if(B != 0) begin
            result = A / B;
            odd = A % B;
        end 
        else begin
            result = 0;
            odd = A;
        end
    end
endmodule
